import { Injectable } from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { JwtPayload } from './jwt.strategy';

@Injectable()
export class AuthService {
  constructor(private jwtService: JwtService) {}

  // This method can be used if you need to generate JWT tokens
  // For AWS API Gateway integration, tokens are typically generated by AWS Cognito or another auth provider
  async generateToken(payload: Omit<JwtPayload, 'iat' | 'exp'>): Promise<string> {
    return this.jwtService.sign(payload);
  }

  // This method can be used to verify tokens if needed
  async verifyToken(token: string): Promise<JwtPayload> {
    return this.jwtService.verify(token);
  }
}
